def apply_nearest_clear_corner(grid):
    """Fill L-shape using nearest clear column to min_col_3s - 1"""
    new_grid = [row[:] for row in grid]

    three_positions = [(r,c) for r in range(10) for c in range(20) if grid[r][c] == 3]
    two_positions = [(r,c) for r in range(10) for c in range(20) if grid[r][c] == 2]

    row_3s = three_positions[0][0]
    min_col_3s = min(c for r,c in three_positions)

    row_2s = two_positions[0][0]
    min_col_2s = min(c for r,c in two_positions)

    start_check = min_col_3s - 1

    def check_clear(col):
        for r in range(min(row_3s, row_2s), max(row_3s, row_2s) + 1):
            if grid[r][col] == 9:
                return False
        return True

    # Find nearest clear column
    best_col = None
    best_dist = float('inf')
    for c in range(0, 20):
        dist = abs(c - start_check)
        if check_clear(c):
            if dist < best_dist:
                best_dist = dist
                best_col = c

    corner_col = best_col

    # Fill vertical arm
    for r in range(min(row_3s, row_2s), max(row_3s, row_2s) + 1):
        new_grid[r][corner_col] = 3

    # Fill horizontal arm
    for c in range(corner_col, min_col_2s):
        new_grid[row_2s][c] = 3

    return new_grid

